      if (pkt.type === 0x1005) {
        const { classId, customName } = pkt.payload;
        const chosen = JOYFUN_CLASSES.find(c => c.id === classId) || JOYFUN_CLASSES[0];
        const finalName = customName && customName.trim().length >= 3 ? customName.trim() : chosen.name;

