const fs = require('fs');
const path = require('path');

function getDimensions(buf) {
  if (buf[0] === 0x89 && buf[1] === 0x50 && buf[2] === 0x4E && buf[3] === 0x47) {
    return { w: buf.readUInt32BE(16), h: buf.readUInt32BE(20), type: 'PNG' };
  }
  if (buf[0] === 0xFF && buf[1] === 0xD8) {
    let offset = 2;
    while (offset < buf.length) {
      if (buf[offset] === 0xFF && (buf[offset + 1] >= 0xC0 && buf[offset + 1] <= 0xC3)) {
        return { h: buf.readUInt16BE(offset + 5), w: buf.readUInt16BE(offset + 7), type: 'JPG' };
      }
      offset += 2 + buf.readUInt16BE(offset + 2);
    }
  }
  return null;
}

function scanDir(dir) {
  if (!fs.existsSync(dir)) return;
  const entries = fs.readdirSync(dir, { withFileTypes: true });
  for (const entry of entries) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      if (!full.includes('node_modules') && !full.includes('.git')) scanDir(full);
    } else if (/\.(png|jpg|jpeg)$/i.test(entry.name)) {
      try {
        const stat = fs.statSync(full);
        if (stat.size > 20000) {
          const fd = fs.openSync(full, 'r');
          const header = Buffer.alloc(2048);
          fs.readSync(fd, header, 0, 2048, 0);
          fs.closeSync(fd);
          const dim = getDimensions(header);
          if (dim && dim.w >= 800) {
            console.log(entry.name + ' -> ' + dim.w + 'x' + dim.h + ' (' + (stat.size / 1024).toFixed(1) + ' KB) | ' + full);
          }
        }
      } catch (e) {}
    }
  }
}

